<?php use App\Helpers\ViewHelper; ?>
<div class="section-heading"><div><p class="eyebrow">Người dùng</p><h2>Quản lý khách hàng</h2><p class="muted">Chỉnh sửa hồ sơ, quyền mua và số dư ví trực tiếp theo từng tài khoản.</p></div><a class="button" href="/admin/reports">Xem phân tích</a></div>
<?php if (empty($customers)): ?><div class="empty-state"><h2>Chưa có khách hàng</h2><p>Khách hàng sẽ xuất hiện sau khi đăng ký tài khoản.</p></div><?php else: ?><div class="table-wrap"><table class="admin-table customer-table"><thead><tr><th>Khách hàng</th><th>Liên hệ</th><th>Đơn hàng</th><th>Đã chi tiêu</th><th>Ví</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($customers as $customer): ?><tr><td><strong><?= ViewHelper::escape($customer['name']) ?></strong><small class="table-subtext">#<?= (int)$customer['id'] ?> · <?= ViewHelper::escape(ViewHelper::userRole((string)$customer['role'])) ?></small></td><td><?= ViewHelper::escape($customer['email']) ?><small class="table-subtext"><?= ViewHelper::escape($customer['phone'] ?? 'Chưa cập nhật') ?></small></td><td><?= (int)$customer['order_count'] ?></td><td><?= ViewHelper::money((int)$customer['total_spent']) ?></td><td><?= ViewHelper::money((int)$customer['wallet_balance']) ?></td><td><?php if ((int)$customer['purchase_blocked'] === 1): ?><span class="report-badge report-badge-blocked">Đã khóa mua</span><?php else: ?><span class="report-badge report-badge-regular">Đang hoạt động</span><?php endif; ?></td><td><a class="action-button" href="/admin/customers/<?= (int)$customer['id'] ?>">Quản lý</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
